import{_ as t,a}from"./chunks/dark-detail.BCYjtFZ4.js";import{_ as r,o as i,c as o,a2 as n}from"./chunks/framework.DDY-poMm.js";const g=JSON.parse('{"title":"BTX Wallet (Web3 wallet)","description":"","frontmatter":{},"headers":[],"relativePath":"wallet/index.md","filePath":"wallet/index.md","lastUpdated":1793861367000}'),s={name:"wallet/index.md"};function l(d,e,c,h,p,f){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="btx-wallet-web3-wallet" tabindex="-1">BTX Wallet (Web3 wallet) <a class="header-anchor" href="#btx-wallet-web3-wallet" aria-label="Permalink to &quot;BTX Wallet (Web3 wallet)&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Private beta</p><p>BTX Wallet is currently in private beta. To learn more or try it, please <a href="/CoinExchange/contact/">contact us</a>.</p></div><p>BTX Wallet is a <strong>self-custody Web3 wallet</strong>: users buy and sell <strong>xStocks tokenized US stocks and ETFs</strong> on-chain directly with USDC / USDT, and their assets always stay in their own on-chain address. They can also join two prediction markets, <a href="/CoinExchange/wallet/predict">BTX Predict and Polymarket</a>. Available as native apps (Android / iOS) and on the web.</p><p>The question users ask most is &quot;which broker is behind this, and where are my shares?&quot; In BTX Wallet every trade and every holding is recorded on the blockchain, so users can verify them themselves on a block explorer.</p><h2 id="how-it-differs-from-the-exchange-app" tabindex="-1">How it differs from the exchange app <a class="header-anchor" href="#how-it-differs-from-the-exchange-app" aria-label="Permalink to &quot;How it differs from the exchange app&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Exchange app</th><th>BTX Wallet</th></tr></thead><tbody><tr><td>Who holds the assets</td><td>The platform</td><td><strong>The user</strong> (private keys never leave the user&#39;s phone)</td></tr><tr><td>Account registration</td><td>Required</td><td><strong>Not required</strong>: create, import or connect an existing wallet and start</td></tr><tr><td>Where trades happen</td><td>Platform matching</td><td><strong>On-chain</strong>, verifiable on a block explorer</td></tr><tr><td>US stock holdings</td><td>Platform ledger</td><td><strong>Tokenized stocks</strong> (xStocks), backed 1:1 by shares held by the issuer</td></tr></tbody></table><h2 id="explore-further" tabindex="-1">Explore further <a class="header-anchor" href="#explore-further" aria-label="Permalink to &quot;Explore further&quot;">​</a></h2><ul><li><a href="/CoinExchange/wallet/trading">Trading and market data</a>: Trade US stocks and ETFs on-chain with USDC / USDT, with charts, company profiles and news</li><li><a href="/CoinExchange/wallet/predict">Predict</a>: BTX Predict and Polymarket sections</li><li><a href="/CoinExchange/wallet/assets">Multi-chain assets and wallet connections</a>: View, receive and send across chains, connect an existing wallet, use the web version</li><li><a href="/CoinExchange/wallet/security">Security</a>: Self-custody, tamper protection and safety notes</li><li><a href="/CoinExchange/wallet/admin">Operator console</a>: What you can manage in the operator console</li></ul><h2 id="screens" tabindex="-1">Screens <a class="header-anchor" href="#screens" aria-label="Permalink to &quot;Screens&quot;">​</a></h2><div style="display:flex;flex-wrap:wrap;gap:28px 20px;justify-content:center;margin:32px 0;"><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+t+'" alt="Home" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>Home</b><br>Price cards, quick actions and today’s top movers </figcaption></figure><figure style="margin:0;flex:0 0 220px;max-width:220px;"><img src="'+a+'" alt="Dark mode" style="border-radius:10px;border:1px solid var(--vp-c-divider);"><figcaption style="text-align:center;font-size:13px;color:var(--vp-c-text-2);margin-top:10px;line-height:1.5;"><b>Dark mode</b><br>Switch between light and dark </figcaption></figure></div><div class="tip custom-block"><p class="custom-block-title">About these screenshots</p><p>These are simulator captures of the beta build (Chinese interface); prices and news come from the test environment.</p></div><p>BTX Wallet is included in the FDE Launch Partner package, with full source code for the wallet app and its console. See <a href="/CoinExchange/intro/pricing">Pricing &amp; Packages</a>.</p>',12)])])}const u=r(s,[["render",l]]);export{g as __pageData,u as default};
